629: function drawMinimap(minimap, racers) {
630:   if (!minimap) return;
631:   const ctx = minimap.ctx;
632:   ctx.clearRect(0, 0, minimap.w, minimap.h);
633:   ctx.drawImage(minimap.off, 0, 0);
634:   for (const r of racers) {
635:     if (!r) continue;
636:     const x = minimap.tx(r.pos.x), z = minimap.tz(r.pos.z);
637:     if (r.isPlayer) {
638:       ctx.save();
639:       ctx.translate(x, z);
640:       ctx.rotate(-r.yaw);
641:       ctx.beginPath();
642:       ctx.moveTo(0, -9);
643:       ctx.lineTo(6.5, 6);
644:       ctx.lineTo(0, 3);
645:       ctx.lineTo(-6.5, 6);
646:       ctx.closePath();
647:       ctx.fillStyle = '#ffffff';
648:       ctx.shadowColor = '#ff6417';
649:       ctx.shadowBlur = 12;
650:       ctx.fill();
651:       ctx.restore();
652:       ctx.fillStyle = '#ff6417';
653:       ctx.beginPath();
654:       ctx.arc(x, z, 3, 0, Math.PI * 2);
655:       ctx.fill();
656:     } else {
657:       ctx.fillStyle = r.accent;
658:       ctx.beginPath();
659:       ctx.arc(x, z, 4.4, 0, Math.PI * 2);
660:       ctx.fill();
661:     }
662:   }
